import './icde_demo.css';
import {fetchJson,postJson} from './api';
import {featureNames as names,labelNames,metricSpecs,escapeHtml as esc,formatMeasurement as value,statusLabel,criterionText,previewCounts,defaultCohort,focusLead,validReview} from './demo_view';

type Obj=Record<string,any>;
type Role='expert'|'patient';
type Section='collaboration'|'evidence'|'cohort'|'review';
const app=document.querySelector<HTMLElement>('#demo')!;
const params=new URLSearchParams(location.search);
const state={
  role:(params.get('role')==='patient'?'patient':'expert') as Role,section:'collaboration' as Section,
  cases:[] as Obj[],ctx:null as Obj|null,evidence:null as Obj|null,selectedFeature:'',
  lead:'II',seconds:10,start:0,allLeads:false,busy:'',error:'',message:'',filter:'',caseFilter:'all',
  cohort:[] as number[],metric:'Q wave count',op:'>=',threshold:1,preview:null as Obj|null,previewStale:false,
  labels:[] as string[],note:'',featureNames:[] as string[],reviewDirty:false,reviewBaseRevision:0,
  messages:[] as Obj[],question:'',feedback:'',patientFeature:'',showFeedback:false,sourceChanged:false,
  collaboration:{revision:0,rounds:[]} as Obj,expertQuestion:'',expertAction:'auto',expertFocus:'',analysisRoundId:null as string|null,
  collaborationLoaded:false,suggestionFeatures:[] as Obj[],
};
const base=()=>`/api/demo/ptbxl/cases/${state.ctx!.sample.ecgId}`;
const activeFeature=()=>state.evidence?.result.features.find((f:Obj)=>f.name===state.selectedFeature)||state.evidence?.result.features[0];
const status=(key:string)=>`<span class="status ${esc(key)}">${esc(statusLabel(key))}</span>`;
const disabled=()=>state.busy?'disabled':'';
const labelChips=(labels:string[],tone='')=>labels?.length?labels.map(l=>`<span class="label-chip ${tone}">${esc(l)}</span>`).join(''):'<span class="muted">No class</span>';
const date=(v:string)=>new Date(v).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const pretty=(f:string)=>names[f]||f.replaceAll('_',' ');

function render(){
  const c=state.ctx,r=c?.publishedReport,patient=state.role==='patient';
  app.innerHTML=`<div class="app-shell ${patient?'patient-mode':''}">
    <header class="app-header"><a class="brand" href="/demo"><span class="brand-mark">R</span><span>RecursiveECG<small>INTERACTIVE RESEARCH DEMO</small></span></a>
      <nav class="role-nav" aria-label="Interaction role"><button data-role="expert" aria-pressed="${!patient}">Clinical Expert</button><button data-role="patient" aria-pressed="${patient}">Patient</button></nav>
      <div class="header-end"><span class="demo-badge">Public data · Demo only</span><a href="/" class="workspace-link">Agent workspace ↗</a></div>
    </header>
    <div class="shell-body ${patient?'patient-shell':''}">${patient?'':caseSidebar()}
    <main class="workspace">
      <div class="workspace-heading"><div><span class="eyebrow">${patient?'PATIENT EXPERIENCE':'EXPERT COLLABORATION'}</span><h1>${patient?'Understand your report':'A second look. Together.'}</h1><p>${patient?'An explanation connected to the same published report.':'Challenge a finding. Inspect the checks. Decide what to keep.'}</p></div>
        ${c?`<div class="record-heading">${patient?`<label for="patient-case">Demo record</label><select id="patient-case" ${disabled()}>${state.cases.map(s=>`<option value="${s.ecgId}" ${s.ecgId===c.sample.ecgId?'selected':''}>ECG ${s.ecgId}</option>`).join('')}</select>`:`<span class="record-label">PTB-XL</span><strong>ECG ${c.sample.ecgId}</strong>`}<details class="provenance"><summary>Source & version</summary><dl><dt>Recorded run</dt><dd>${esc(c.iteration)}</dd><dt>Evidence tool</dt><dd>${esc(c.toolVersion)}</dd><dt>Report</dt><dd>${r?'Published v'+r.revision:'Not published'}</dd><dt>Context</dt><dd>${esc(c.contextId)}</dd></dl></details></div>`:''}
      </div>
      ${state.error?`<div class="notice error" role="alert">${esc(state.error)} ${c?'<button id="reload-case" class="text-button">Refresh this record</button>':''}</div>`:''}
      ${state.message?`<div class="notice success" role="status">${esc(state.message)}<button id="dismiss-message" aria-label="Dismiss notification">×</button></div>`:''}
      ${c?patient?patientPage():expertPage():`<section class="surface loading"><span class="spinner"></span><h2>${state.error?'Records unavailable':'Loading recorded ECGs'}</h2><p>Retrieving the signal, model output and saved review.</p>${state.error?'<button id="retry-cases" class="primary">Try again</button>':''}</section>`}
      <footer class="workspace-footer"><span>Public ECG dataset. Demonstration reviews do not establish a clinical diagnosis.</span><span>Source predictions remain unchanged.</span></footer>
    </main></div>${state.busy?`<div class="busy-toast" role="status"><span class="spinner"></span>${esc(state.busy)}</div>`:''}
  </div>`;
  bind();
}
function caseSidebar(){
  const featured=[26,3919,62];
  return `<aside class="case-sidebar"><div class="rail-title"><span class="eyebrow">CASE LIBRARY</span><span>${state.cases.length}</span></div><label class="sr-only" for="case-search">Find ECG ID</label><input id="case-search" type="search" placeholder="Find ECG ID…" value="${esc(state.filter)}"/>
    <div class="case-filters" role="group" aria-label="Case filter"><button data-filter="all" aria-pressed="${state.caseFilter==='all'}">All records</button><button data-filter="disagreement" aria-pressed="${state.caseFilter==='disagreement'}">Disagreement</button></div>
    <div class="case-list">${[...state.cases].sort((a,b)=>(featured.includes(a.ecgId)?featured.indexOf(a.ecgId):-1)<0?featured.includes(b.ecgId)?1:0:featured.includes(b.ecgId)?featured.indexOf(a.ecgId)-featured.indexOf(b.ecgId):-1).map(c=>`<button class="case-choice ${state.ctx?.sample.ecgId===c.ecgId?'active':''}" data-case="${c.ecgId}" data-exact="${c.exact}" ${caseVisible(c)?'':'hidden'} ${disabled()} aria-pressed="${state.ctx?.sample.ecgId===c.ecgId}"><span class="case-line"><strong>ECG ${c.ecgId}</strong><span class="case-dot ${c.exact?'':'disagreement'}"></span></span><span class="case-class">${esc(c.predicted.join(' + ')||'No class')}</span><small>${c.ecgId===26?'Explore multiple findings':c.ecgId===3919?'Inspect a disagreement':c.ecgId===62?'Explore report dialogue':c.exact?'Reference agreement':'Prediction disagreement'}</small></button>`).join('')}</div>
    <div class="rail-foot"><span class="case-dot disagreement"></span> Dataset / model disagreement<p>These labels are separate from expert review.</p></div></aside>`;
}
function caseVisible(c:Obj){return String(c.ecgId).includes(state.filter)&&(state.caseFilter!=='disagreement'||!c.exact);}
function expertPage(){
  const c=state.ctx!,r=c.publishedReport;
  return `<div class="case-context"><div><span>Dataset labels</span><div>${labelChips(c.sample.truth)}</div></div><span class="context-divider">${c.sample.exact?'=':'≠'}</span><div><span>Model output</span><div>${labelChips(c.sample.predicted)}</div></div><div class="context-assessment"><span>${c.sample.exact?'Reference agreement':'Prediction disagreement'}</span><small>${c.sample.exact?'Agreement is not clinical verification.':'Inspect evidence; do not infer a diagnosis from this difference.'}</small></div><div class="context-report"><span>${r?'Published report v'+r.revision:'Not yet published'}</span><small>${state.reviewDirty?'Unsaved review changes':c.review?.status==='draft'?'Draft v'+c.review.revision+' saved':'Expert review is a separate record'}</small></div></div>
    <nav class="work-tabs" aria-label="Expert workspace section">${([['collaboration','01','Collaborate'],['evidence','02','Evidence'],['cohort','03','Criterion preview'],['review','04','Report & feedback']] as const).map(([key,n,label])=>`<button data-section="${key}" aria-pressed="${state.section===key}"><span>${n}</span>${label}${key==='review'&&c.feedback.length?`<b>${c.feedback.length}</b>`:''}</button>`).join('')}<span class="tab-hint">Your judgment stays in control</span></nav>
    ${state.section==='collaboration'?collaborationWorkspace():state.section==='evidence'?evidenceWorkspace():state.section==='cohort'?cohortWorkspace():reviewWorkspace()}`;
}

function collaborationWorkspace(){
  const rounds=state.collaboration.rounds as Obj[],last=rounds.at(-1);
  const prompts=last?last.nextChecks:['Summarize the evidence and its limitations for this case.','Which findings need stronger evidence, and why?','Can these measurements explain the model output?'];
  const available=state.evidence?.result.features||last?.features||[];
  return `<div class="collab-layout"><section class="surface collab-main"><div class="panel-heading"><div><span class="eyebrow">CASE REVIEW PARTNER</span><h2>${last?'What should we check next?':'Start with a question, not a blank report.'}</h2><p class="muted">The assistant checks evidence and prepares a suggestion. You can challenge it, reject it or edit it.</p></div><span class="count">${rounds.length} rounds</span></div>
    <div class="collab-history" aria-live="polite">${rounds.length?rounds.map((r,i)=>`<article class="collab-round"><div class="round-heading"><span>ROUND ${i+1}</span><span class="decision-${esc(r.decision)}">${r.decision==='accepted'?'Accepted for draft':r.decision==='rejected'?'Rejected':i===rounds.length-1?'Awaiting your judgment':'Previous suggestion'}</span></div><div class="expert-message"><span>YOUR QUESTION${r.focus?' · '+esc(pretty(r.focus)):''}</span><p>${esc(r.message)}</p></div><div class="agent-response"><span>REVIEW ASSISTANT · MODEL-GENERATED</span><p>${esc(r.response)}</p></div><details class="check-receipt" ${i===rounds.length-1?'open':''}><summary>What the system actually checked</summary><p class="micro">${esc(r.plan.reason)}</p>${r.checks.map((x:Obj)=>`<div class="check-item ${esc(x.status)}"><strong>${esc(x.name)}</strong><p>${esc(x.detail)}</p></div>`).join('')}${r.measurementChanges.length?`<p class="micro">Changed measurements: ${r.measurementChanges.map((x:Obj)=>esc(pretty(x.name))).join(', ')}</p>`:''}</details>${i!==rounds.length-1?`<details><summary>Suggestion from round ${i+1}</summary><p class="proposal-note">${esc(r.draftNote)}</p></details>`:''}</article>`).join(''):`<div class="collab-welcome"><span class="assistant-monogram">R</span><h3>You bring the question. We help investigate.</h3><p>Ask about a finding, challenge a measurement, or check the supporting sources. Start with an evidence summary if you are not sure where to begin.</p><button id="start-collaboration" class="primary" ${disabled()}>Prepare an initial analysis ↗</button><small>No diagnosis labels are selected or published automatically.</small></div>`}</div>
    <div class="collab-composer"><div class="followup-prompts">${prompts.map((p:string)=>`<button data-expert-prompt="${esc(p)}" ${disabled()}>${esc(p)}</button>`).join('')}</div><form id="expert-question-form"><label for="expert-question">Your question or objection</label><textarea id="expert-question" rows="3" minlength="3" maxlength="2000" placeholder="例如：这个判断依据不足。请检查相关测量和来源，说明哪些能支持、哪些还不能确定。">${esc(state.expertQuestion)}</textarea><div class="collab-controls"><label>Check<select id="expert-action" ${disabled()}>${[['auto','Let the assistant choose'],['review_evidence','Review available evidence'],['rerun_measurements','Re-run measurements'],['audit_sources','Check attached sources']].map(([v,l])=>`<option value="${v}" ${state.expertAction===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Focus<select id="expert-focus" ${disabled()}><option value="">Whole case</option>${available.map((f:Obj)=>`<option value="${esc(f.name)}" ${state.expertFocus===f.name?'selected':''}>${esc(pretty(f.name))}</option>`).join('')}</select></label><button class="primary" ${disabled()}>${state.busy?'Checking…':'Investigate & respond ↗'}</button></div></form><p class="micro">Questions in English or Chinese. Real tool checks, followed by a model-generated suggestion. Model predictions never change here. Reports change only when explicitly saved or published.</p></div></section>
    <aside class="collab-side"><section class="surface suggestion-panel"><span class="eyebrow">${last?'LATEST SUGGESTION · ROUND '+rounds.length:'YOUR NEXT REVIEW'}</span><h2>${last?'Review the proposed revision':'A draft you can question'}</h2>${last?`<p class="micro">Not published · Requires your review</p><div class="proposal-note">${esc(last.draftNote)}</div><details class="note-diff"><summary>Compare with ${rounds.length>1?'previous suggestion':'existing note'}</summary>${last.diff.map((d:Obj)=>`<div class="diff-${esc(d.kind)}"><span>${d.kind==='added'?'+':d.kind==='removed'?'−':' '}</span><p>${esc(d.text)}</p></div>`).join('')}</details><div class="unresolved"><h3>Still unresolved</h3>${last.unresolved.length?`<ul>${last.unresolved.map((u:string)=>`<li>${esc(u)}</li>`).join('')}</ul>`:'<p class="micro">No additional items listed by the assistant. This is not clinical verification.</p>'}</div><div class="proposal-evidence"><h3>Evidence used</h3>${last.features.map((f:Obj)=>`<button class="text-button" data-collab-evidence="${esc(f.name)}">${esc(pretty(f.name))} · ${esc(value(f))} ↗</button>`).join('')||'<p class="micro">No measurements attached to this suggestion.</p>'}</div>${last.decision==='pending'?`<div class="suggestion-actions"><button id="accept-suggestion" class="primary" ${disabled()}>Accept into editable draft →</button><button id="challenge-suggestion" class="quiet-button" ${disabled()}>Challenge this suggestion</button><button id="reject-suggestion" class="text-button" ${disabled()}>Reject suggestion</button></div>`:`<p class="decision-receipt">${last.decision==='accepted'?'Accepted for a draft. Publication is a separate decision.':'Rejected. Your published report is unchanged. Ask a follow-up to continue.'}</p>${last.decision==='accepted'?'<button id="restore-suggestion" class="quiet-button">Open suggestion in draft →</button>':''}`}`:`<div class="empty-suggestion"><p>The assistant will return an analysis, an editable note and the questions it cannot resolve.</p><p>Compare revisions here. Accept only what you agree with.</p></div>`}</section><section class="surface collab-boundary"><h3>You stay in control</h3><p>Accepting fills a local draft. Choose review labels explicitly and publish only after checking the note.</p><p>Re-running uses the existing full-record tool. No model training, software modification or new clinical diagnosis.</p><button data-section="evidence" class="text-button">Inspect the underlying evidence →</button></section></aside></div>`;
}
function signalPlot(lead:Obj,overview=false){
  const w=state.ctx!.waveform,max=Math.max(2,Math.ceil(Math.max(...w.leads.flatMap((l:Obj)=>l.values.map((v:number)=>Math.abs(v))))));
  const duration=overview?w.durationSeconds:Math.min(state.seconds,w.durationSeconds),start=overview?0:Math.min(state.start,w.durationSeconds-duration);
  const values=lead.values.slice(Math.floor(start*w.sampleRate),Math.min(lead.values.length,Math.ceil((start+duration)*w.sampleRate)+1));
  const width=1000,height=overview?100:210,pad=overview?10:20;
  const d=values.map((v:number,i:number)=>`${i?'L':'M'}${(pad+i/Math.max(1,values.length-1)*(width-2*pad)).toFixed(2)},${(height/2-v/max*(height*.42)).toFixed(2)}`).join(' ');
  const gridId=`grid-${lead.name}-${overview?'all':'single'}`;
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Recorded lead ${esc(lead.name)}, ${start.toFixed(1)} to ${(start+duration).toFixed(1)} seconds, plus or minus ${max} mV"><defs><pattern id="${gridId}" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#eadbd9" stroke-width=".6"/></pattern></defs><rect width="1000" height="${height}" fill="url(#${gridId})"/><path d="${d}" fill="none" stroke="#22474b" stroke-width="${overview?1.4:1.8}" vector-effect="non-scaling-stroke"/></svg>`;
}
function waveform(){
  const w=state.ctx!.waveform,lead=w.leads.find((l:Obj)=>l.name===state.lead)||w.leads[0],max=Math.max(2,Math.ceil(Math.max(...w.leads.flatMap((l:Obj)=>l.values.map((v:number)=>Math.abs(v))))));
  const start=Math.min(state.start,Math.max(0,w.durationSeconds-state.seconds)),end=Math.min(w.durationSeconds,start+state.seconds);
  return `<section class="surface waveform-surface"><div class="panel-heading"><div><span class="eyebrow">RECORDED SIGNAL</span><h2>ECG waveform <span>${w.durationSeconds}s · ${w.sampleRate} Hz</span></h2></div><button class="quiet-button" id="toggle-leads" aria-pressed="${state.allLeads}">${state.allLeads?'Single lead':'12-lead overview'}</button></div>
    ${state.allLeads?`<div class="all-leads">${w.leads.map((l:Obj)=>`<button class="mini-lead" data-lead="${esc(l.name)}"><span>${esc(l.name)}</span>${signalPlot(l,true)}</button>`).join('')}</div>`:`<div class="lead-selector" aria-label="Focus lead">${w.leads.map((l:Obj)=>`<button data-lead="${esc(l.name)}" aria-pressed="${lead.name===l.name}">${esc(l.name)}</button>`).join('')}</div><div class="signal-paper"><span class="signal-lead">${esc(lead.name)}</span>${signalPlot(lead)}<div class="time-axis">${Array.from({length:6},(_,i)=>`<span>${Number((start+(end-start)*i/5).toFixed(1))}s</span>`).join('')}</div></div><div class="signal-controls"><span>View window</span><div>${[10,4,2].map(n=>`<button data-window="${n}" aria-pressed="${state.seconds===n}">${n}s</button>`).join('')}</div>${state.seconds<w.durationSeconds?`<label for="signal-start">Start</label><input id="signal-start" aria-label="Signal window start" type="range" min="0" max="${Math.max(0,w.durationSeconds-state.seconds)}" step=".1" value="${start}"/><output>${start.toFixed(1)}s</output>`:''}<span class="amplitude">±${max} mV</span></div>`}
    <p class="micro">View controls only. Evidence measurements use the complete record; this is not a selected-segment measurement.</p></section>`;
}
function evidenceWorkspace(){
  const e=state.evidence;
  return `<div class="evidence-layout"><div class="signal-column">${waveform()}<section class="surface measurements-surface"><div class="panel-heading"><div><span class="eyebrow">EXECUTABLE EVIDENCE</span><h2>${e?'Measured on this record':'Inspect the evidence behind a finding'}</h2></div><button id="run-evidence" class="primary" ${disabled()}>${e?'Run again':'Run evidence check'} <span>↗</span></button></div>
      ${e?`<div class="execution-receipt"><span class="receipt-dot"></span>${e.cached?'Cached result retrieved':'Tool executed'}<span>${e.elapsedMs} ms</span><span>${e.result.features.length} measurements</span></div><div class="measurement-grid">${e.result.features.map((f:Obj)=>`<button class="measurement ${f.name===activeFeature()?.name?'selected':''}" data-feature="${esc(f.name)}" aria-pressed="${f.name===activeFeature()?.name}"><span>${esc(pretty(f.name))}</span><strong>${esc(value(f))}</strong><small><span class="metric-dot ${esc(f.judgment.status)}"></span>${esc(statusLabel(f.judgment.status))}${state.featureNames.includes(f.name)?' · Attached':''}</small></button>`).join('')}</div><details class="quality-details"><summary>Measurement quality & limitations</summary><p>${e.result.quality.beats_detected} detected beats · ${e.result.quality.leads_with_qrs_bounds} leads measured</p>${[...e.result.warnings.map((w:Obj)=>w.message),...e.result.adapterNotes].map(t=>`<p>${esc(t)}</p>`).join('')}</details>`:`<div class="evidence-prompt"><span class="step-marker">01</span><div><h3>A result you can check, not just read.</h3><p>Run the existing reference feature tool. Select a measurement to inspect its rule and source.</p></div></div><div class="evidence-route"><span>Recorded signal</span><b>→</b><span>Measurement</span><b>→</b><span>Reference</span></div>`}
    </section></div><aside class="surface evidence-inspector">${evidenceInspector()}</aside></div><div class="evidence-tray"><div><strong>${state.featureNames.length} measurements attached</strong><span>to your review draft</span></div><button data-section="cohort" class="quiet-button">Preview a condition →</button><button data-section="review" class="primary">Compose report →</button></div>`;
}
function evidenceInspector(){
  const f=activeFeature();
  if(!f)return `<span class="eyebrow">EVIDENCE INSPECTOR</span><h2>Follow a finding to its source</h2><div class="inspector-placeholder">${[['01','Measurement','A value from the recorded ECG'],['02','Reference rule','The condition used to assess it'],['03','Source excerpt','The original supporting text']].map(([n,t,d])=>`<div><span>${n}</span><section><h3>${t}</h3><p>${d}</p></section></div>`).join('')}</div><p class="micro">The evidence tool supports review. Its measurements do not explain the classifier’s internal decision.</p>`;
  const target=focusLead(f,state.ctx!.waveform.leads.map((l:Obj)=>l.name));
  return `<div class="inspector-top"><span class="eyebrow">EVIDENCE INSPECTOR</span><span class="inspect-tag">SELECTED</span></div><h2>${esc(pretty(f.name))}</h2>
    <section class="evidence-stage"><span class="stage-index">01</span><div><h3>Measurement</h3><div class="measurement-value">${esc(value(f))}</div>${status(f.judgment.status)}<p class="micro">${f.name==='qrs_duration_ms'?'Tool-reported aggregate across measured leads.':'Assessment of this measurement under the tool’s reference rule.'}</p>${target?`<button id="focus-measured-lead" class="text-button">View lead ${esc(target)} in waveform ↗</button><p class="micro">Lead focus only; no beat boundaries are provided by this result.</p>`:''}<details><summary>Measurement details</summary><pre>${esc(JSON.stringify(f.value,null,2))}</pre></details></div></section>
    <section class="evidence-stage"><span class="stage-index">02</span><div><h3>Reference rule</h3><p class="rule-text">${esc(f.judgment.rule)}</p></div></section>
    <section class="evidence-stage source-stage"><span class="stage-index">03</span><div><h3>Source excerpt</h3><span class="micro">Original reference text</span>${f.evidence.map((e:Obj)=>`<blockquote><p>${esc(e.quote)}</p><cite>${esc(e.section|| (e.page?'Page '+e.page:'Reference excerpt'))}</cite><a href="/api/references/preview?path=${encodeURIComponent(e.referencePath)}${e.page?'#page='+encodeURIComponent(e.page):''}" target="_blank" rel="noopener">Open source document ↗</a></blockquote>`).join('')}</div></section>
    <button class="quiet-button" data-challenge-feature="${esc(f.name)}">Question this evidence ↗</button><label class="attach-control"><input type="checkbox" data-attach="${esc(f.name)}" ${state.featureNames.includes(f.name)?'checked':''}/>Include this evidence in the review</label>`;
}
function cohortWorkspace(){
  const spec=metricSpecs[state.metric],p=state.preview,counts=p?previewCounts(p.rows):null;
  return `<section class="surface cohort-workspace"><div class="panel-heading"><div><span class="eyebrow">BOUNDED CRITERION PREVIEW</span><h2>One condition. Compare its impact across cases.</h2><p class="muted">Choose a measurement and records. Only review flags are previewed.</p></div><span class="immutable-badge">Model predictions unchanged</span></div>
    <form id="criterion-form"><div class="condition-builder"><label>Measurement<select id="criterion-metric">${Object.entries(metricSpecs).map(([k,v])=>`<option value="${k}" ${state.metric===k?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Condition<select id="criterion-op">${['>=','>','<=','<'].map(op=>`<option value="${esc(op)}" ${state.op===op?'selected':''}>${esc(op.replace('>=','≥').replace('<=','≤'))}</option>`).join('')}</select></label><label>Threshold<div class="unit-input"><input id="criterion-threshold" type="number" step="any" min="0" max="10000" required value="${state.threshold}"/><span>${spec.unit}</span></div></label><div class="condition-action"><span>Action</span><strong>Needs review</strong></div><button class="primary" ${disabled()}>Preview impact →</button></div><p class="micro">Supported measurements: QRS duration, PR interval and Q-wave count. This is a bounded rule, not unrestricted clinical language.</p></form>
    <div class="cohort-select"><div><h3>Records to compare <span>${state.cohort.length} / 8</span></h3><p class="micro">The selection stays fixed while you compare thresholds.</p></div><div class="cohort-chips">${state.cohort.map(id=>`<button data-remove-cohort="${id}" aria-label="Remove ECG ${id} from preview">ECG ${id}<span>×</span></button>`).join('')}<label class="sr-only" for="cohort-add">Add record to preview</label><select id="cohort-add" ${state.cohort.length>=8?'disabled':''}><option value="">+ Add record</option>${state.cases.filter(c=>!state.cohort.includes(c.ecgId)).map(c=>`<option value="${c.ecgId}">ECG ${c.ecgId}</option>`).join('')}</select></div></div>
    ${p?`${state.previewStale?'<div class="notice warning">Inputs changed. The results below belong to the previous preview. Run Preview impact to update them.</div>':''}<div class="preview-summary"><div><span>PREVIEW RESULT</span><h3>${esc(p.criterion.text)}</h3></div><div><strong>${counts!.flagged}</strong><span>flagged</span></div><div><strong>${counts!.clear}</strong><span>not flagged</span></div><div><strong>${counts!.unknown}</strong><span>not assessable</span></div></div><div class="table-scroll"><table><thead><tr><th>Record</th><th>Measured value</th><th>Reference assessment</th><th>Preview outcome</th><th></th></tr></thead><tbody>${p.rows.map((r:Obj)=>`<tr class="${r.matched===true?'flagged':''}"><td><b>ECG ${r.ecgId}</b></td><td>${r.value==null?'Not measurable':esc(r.value+' '+p.criterion.unit)}</td><td>${status(r.originalStatus)}</td><td><span class="preview-outcome ${r.matched===true?'flag':r.matched==null?'unknown':''}">${r.matched===true?'Needs review':r.matched===false?'No new flag':'Cannot determine'}</span></td><td><button data-inspect-case="${r.ecgId}" class="text-button" ${disabled()}>Inspect →</button></td></tr>`).join('')}</tbody></table></div><div class="preview-foot"><p>${counts!.flagged===0?'No selected record met this condition. This is a valid preview result.':'A review flag is an invitation to inspect, not a diagnosis.'}</p><span>${p.rows.length} selected records · Preview only · Not applied</span></div>`:`<div class="preview-empty"><span class="step-marker">02</span><h3>See which records meet your condition</h3><p>Matched, unmatched and unavailable measurements remain separate.</p><span class="micro">Example: Q wave count ≥ 1 across the selected public records.</span></div>`}
  </section>`;
}
function selectedDraftFeatures(){const available=[...state.suggestionFeatures,...(state.evidence?.result.features||[]),...(state.ctx?.review?.features||[])];return state.featureNames.map(n=>available.find((f:Obj)=>f.name===n)).filter(Boolean);}
function reviewWorkspace(){
  const c=state.ctx!,r=c.publishedReport,features=selectedDraftFeatures();
  return `<div class="review-layout"><section class="surface review-editor"><div class="panel-heading"><div><span class="eyebrow">EXPERT REVIEW</span><h2>Compose an evidence-backed report</h2></div><span class="draft-indicator">${state.reviewDirty?'Unsaved changes':c.review?.status==='draft'?'Draft saved':'Review draft'}</span></div>
    ${state.analysisRoundId?'<div class="notice success">Assistant suggestion loaded into your draft. Edit it, choose labels and review before publishing.</div>':'<button data-section="collaboration" class="quiet-button">Ask the assistant to prepare a draft →</button>'}<form id="review-form"><fieldset><legend>Demo review labels <span>Choose explicitly; model labels are not copied into a new review.</span></legend><div class="review-labels">${Object.keys(labelNames).map(l=>`<label><input type="checkbox" name="review-label" value="${l}" ${state.labels.includes(l)?'checked':''}/> ${l}</label>`).join('')}</div></fieldset><label for="review-note">Review note & uncertainty</label><textarea id="review-note" rows="7" minlength="10" maxlength="3000" required placeholder="Describe the observations you reviewed, the supporting evidence and what remains uncertain. Do not use the dataset label as a substitute for clinical review.">${esc(state.note)}</textarea>
    <div class="attached-evidence"><h3>Attached evidence <span>${features.length}</span></h3>${features.length?features.map((f:Obj)=>`<div><span>${esc(pretty(f.name))}</span><strong>${esc(value(f))}</strong><button data-detach="${esc(f.name)}" type="button" aria-label="Remove ${esc(pretty(f.name))} from draft">×</button></div>`).join(''):'<p class="muted">No measurements attached yet. Select evidence in the inspector.</p>'}<button type="button" data-section="evidence" class="text-button">Choose supporting evidence →</button></div>
    <div class="review-actions"><button type="button" id="save-draft" class="quiet-button" ${disabled()}>Save draft</button><button class="primary" ${state.busy||state.sourceChanged?'disabled':''}>Publish demo report →</button></div><p class="micro">Publication saves a versioned demonstration review. It does not verify clinician identity or change the model.</p></form></section>
    <aside class="review-side"><section class="surface publication-panel"><span class="eyebrow">PATIENT HANDOFF</span><h2>${r?'Published report v'+r.revision:'Your review becomes the patient’s context'}</h2>${r?`<div class="published-labels">${labelChips(r.labels,'published')}</div><p class="published-note">${esc(r.note)}</p><div class="publication-receipt"><span>${r.features.length} measurements attached</span><span>${esc(date(r.updatedAt))}</span></div><button data-role="patient" class="primary">Open patient report →</button>`:`<div class="handoff-items"><p><b>Review note</b>Observations and uncertainty</p><p><b>Attached measurements</b>Evidence selected by the reviewer</p><p><b>Report version</b>The context supplied to patient Q&A</p></div><p class="micro">No report is visible to the patient until it is published.</p>`}</section>
    <section class="surface feedback-panel"><div class="panel-heading"><div><span class="eyebrow">CLARIFICATION QUEUE</span><h2>Questions from the patient</h2></div><span class="count">${c.feedback.length}</span></div>${c.feedback.length?c.feedback.map((f:Obj)=>`<article class="feedback-item"><span>Report v${f.reportRevision} · Awaiting clarification</span><p>${esc(f.text)}</p><small>${esc(date(f.createdAt))}</small></article>`).join(''):'<p class="muted">Requests linked to this report will appear here.</p>'}<p class="micro">This demo records requests; an expert-reply workflow is not implemented.</p></section></aside></div>`;
}
function patientPage(){
  const c=state.ctx!,r=c.publishedReport;
  if(!r)return `<section class="surface patient-pending"><span class="eyebrow">REVIEW PENDING</span><h2>This record has no published demo report.</h2><p>A model output is not a reviewed report. The patient explanation opens after a reviewer publishes their note.</p><button data-role="expert" class="primary">Open expert workspace →</button><button data-case="62" class="quiet-button" ${disabled()}>View demo record 62</button></section>`;
  return `<div class="patient-version-strip"><span class="published-dot"></span><strong>Published demo report · v${r.revision}</strong><span>Same report. Same attached evidence.</span><small>ECG ${c.sample.ecgId} · ${esc(date(r.updatedAt))}</small></div><div class="patient-layout"><section class="surface patient-report"><div class="report-heading"><span class="eyebrow">YOUR REPORT</span><span class="report-number">v${r.revision}</span></div><h2>ECG review summary</h2><p class="micro">Public dataset example, not a personal clinical report.</p>
    <div class="report-findings">${r.labels.map((l:string)=>`<article><span class="finding-abbr">${esc(l)}</span><div><h3>${esc(labelNames[l]||l)}</h3><button data-question="What does ${esc(l)} mean in this report?" class="text-button">Explain this finding →</button></div></article>`).join('')}</div><div class="report-note"><h3>Reviewer’s note</h3><p>${esc(r.note)}</p><button data-question="Please explain the review note in simpler words." class="text-button">Explain in plain language →</button></div>
    <div class="patient-measurements"><div class="panel-heading"><h3>Evidence attached to this report</h3><span class="count">${r.features.length}</span></div>${r.features.length?r.features.map((f:Obj)=>`<button class="patient-measurement ${state.patientFeature===f.name?'focused':''}" data-patient-feature="${esc(f.name)}"><span>${esc(pretty(f.name))}</span><strong>${esc(value(f))}</strong><small>Ask about this measurement →</small></button>`).join(''):'<p class="muted">No measurements were attached to this version.</p>'}</div><div class="report-footnote">A finding does not establish its cause. Clinical interpretation needs the wider medical context.</div></section>
    <section class="surface conversation"><div class="panel-heading"><div><span class="eyebrow">REPORT ASSISTANT</span><h2>Ask. Understand. Clarify.</h2></div><span class="context-badge">Report v${r.revision}</span></div><p class="muted">Answers receive the saved note, review labels and attached measurements.</p><div class="dialogue-messages" aria-live="polite">${state.messages.length?state.messages.map(m=>`<article class="dialogue-message ${m.role} ${m.source==='error'?'service-error':''}"><span>${m.role==='user'?'YOU':m.source==='safety'?'SAFETY GUIDANCE':m.source==='error'?'SERVICE NOTICE':'REPORT ASSISTANT'}</span><p>${esc(m.text)}</p>${m.contextUsed?`<details><summary>Report context supplied · v${m.reportRevision}</summary><p>${esc(m.contextUsed.note)}</p><div>${m.contextUsed.features.map((f:string)=>`<button class="context-link" data-patient-feature="${esc(f)}">${esc(pretty(f))}</button>`).join('')}</div><small>These are the inputs supplied to the model, not verified sentence-level citations.</small></details>`:''}</article>`).join(''):`<div class="conversation-welcome"><span class="assistant-monogram">R</span><h3>Start with what matters to you.</h3><p>Ask about a finding, its evidence or what remains uncertain.</p></div>`}</div>
    <div class="suggested-questions">${['What does this report mean?','What remains uncertain?','What evidence was attached?'].map(q=>`<button data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="question-form"><label class="sr-only" for="patient-question">Ask about this report</label><div class="question-input"><input id="patient-question" maxlength="500" required placeholder="Ask about this report…" value="${esc(state.question)}"/><button class="primary" ${disabled()}>Ask →</button></div></form><p class="micro">Report explanation only. No individualized diagnosis or treatment.</p>
    <div class="clarification"><button id="toggle-feedback" class="clarification-toggle" aria-expanded="${state.showFeedback}"><span>Still unclear? Ask the expert to clarify.</span><span>${state.showFeedback?'−':'+'}</span></button>${state.showFeedback?`<form id="feedback-form"><label for="patient-feedback">What would you like clarified?</label><textarea id="patient-feedback" rows="3" minlength="3" maxlength="1000" required placeholder="Describe the part of the report you do not understand…">${esc(state.feedback)}</textarea><button class="quiet-button" ${disabled()}>Send clarification request →</button></form>`:''}${c.feedback.length?`<div class="patient-requests">${c.feedback.slice(-3).map((f:Obj)=>`<div><span class="request-status">Awaiting clarification · v${f.reportRevision}</span><p>${esc(f.text)}</p></div>`).join('')}</div>`:''}</div></section></div>`;
}

function urlState(){history.replaceState({},'',`/demo?role=${state.role}${state.ctx?'&case='+state.ctx.sample.ecgId:''}`);}
function updateCaseFilter(){app.querySelectorAll<HTMLElement>('.case-choice').forEach(el=>{el.hidden=!String(el.dataset.case).includes(state.filter)||(state.caseFilter==='disagreement'&&el.dataset.exact==='true');});}
function setQuestion(q:string){state.question=q;render();app.querySelector<HTMLInputElement>('#patient-question')?.focus();}
function markPreviewStale(){state.previewStale=Boolean(state.preview);}
function bind(){
  app.querySelector('#expert-question-form')?.addEventListener('submit',e=>{e.preventDefault();void investigate();});
  app.querySelector<HTMLTextAreaElement>('#expert-question')?.addEventListener('input',e=>state.expertQuestion=(e.target as HTMLTextAreaElement).value);
  app.querySelector<HTMLSelectElement>('#expert-action')?.addEventListener('change',e=>state.expertAction=(e.target as HTMLSelectElement).value);
  app.querySelector<HTMLSelectElement>('#expert-focus')?.addEventListener('change',e=>state.expertFocus=(e.target as HTMLSelectElement).value);
  app.querySelector('#start-collaboration')?.addEventListener('click',()=>{state.expertQuestion='Summarize the evidence for this case, identify unsupported conclusions, and prepare a cautious research-review draft.';state.expertAction='auto';void investigate();});
  app.querySelectorAll<HTMLElement>('[data-expert-prompt]').forEach(el=>el.onclick=()=>{state.expertQuestion=el.dataset.expertPrompt!;render();app.querySelector<HTMLTextAreaElement>('#expert-question')?.focus();});
  app.querySelectorAll<HTMLElement>('[data-challenge-feature]').forEach(el=>el.onclick=()=>{state.expertFocus=el.dataset.challengeFeature!;state.expertQuestion=`Is the ${pretty(state.expertFocus)} evidence sufficient? Check its limitations and supporting source.`;state.expertAction='auto';state.section='collaboration';render();app.querySelector<HTMLTextAreaElement>('#expert-question')?.focus();});
  app.querySelectorAll<HTMLElement>('[data-collab-evidence]').forEach(el=>el.onclick=()=>void openCollaborationEvidence(el.dataset.collabEvidence!));
  app.querySelector('#accept-suggestion')?.addEventListener('click',()=>void decideSuggestion('accepted'));
  app.querySelector('#reject-suggestion')?.addEventListener('click',()=>void decideSuggestion('rejected'));
  app.querySelector('#restore-suggestion')?.addEventListener('click',()=>useSuggestion());
  app.querySelector('#challenge-suggestion')?.addEventListener('click',()=>{state.expertQuestion='I am not convinced by this suggestion. Please re-check ';render();app.querySelector<HTMLTextAreaElement>('#expert-question')?.focus();});
  app.querySelectorAll<HTMLElement>('[data-role]').forEach(el=>el.onclick=()=>{state.role=el.dataset.role as Role;state.error='';state.message='';urlState();render();});
  app.querySelectorAll<HTMLElement>('[data-section]').forEach(el=>el.onclick=()=>{state.section=el.dataset.section as Section;render();});
  app.querySelectorAll<HTMLElement>('[data-case]').forEach(el=>el.onclick=()=>void loadCase(Number(el.dataset.case)));
  app.querySelectorAll<HTMLElement>('[data-inspect-case]').forEach(el=>el.onclick=()=>void inspectCase(Number(el.dataset.inspectCase)));
  app.querySelector<HTMLInputElement>('#case-search')?.addEventListener('input',e=>{state.filter=(e.target as HTMLInputElement).value;updateCaseFilter();});
  app.querySelectorAll<HTMLElement>('[data-filter]').forEach(el=>el.onclick=()=>{state.caseFilter=el.dataset.filter!;render();});
  app.querySelector<HTMLSelectElement>('#patient-case')?.addEventListener('change',e=>void loadCase(Number((e.target as HTMLSelectElement).value)));
  app.querySelector('#dismiss-message')?.addEventListener('click',()=>{state.message='';render();});
  app.querySelector('#reload-case')?.addEventListener('click',()=>void refreshContext());
  app.querySelector('#retry-cases')?.addEventListener('click',()=>void init());
  app.querySelectorAll<HTMLElement>('[data-lead]').forEach(el=>el.onclick=()=>{state.lead=el.dataset.lead!;state.allLeads=false;render();});
  app.querySelectorAll<HTMLElement>('[data-window]').forEach(el=>el.onclick=()=>{state.seconds=Number(el.dataset.window);state.start=Math.min(state.start,Math.max(0,state.ctx!.waveform.durationSeconds-state.seconds));render();});
  app.querySelector<HTMLInputElement>('#signal-start')?.addEventListener('change',e=>{state.start=Number((e.target as HTMLInputElement).value);render();});
  app.querySelector('#toggle-leads')?.addEventListener('click',()=>{state.allLeads=!state.allLeads;render();});
  app.querySelector('#focus-measured-lead')?.addEventListener('click',()=>{const l=focusLead(activeFeature(),state.ctx!.waveform.leads.map((l:Obj)=>l.name));if(l){state.lead=l;state.allLeads=false;render();}});
  app.querySelector('#run-evidence')?.addEventListener('click',()=>void runEvidence());
  app.querySelectorAll<HTMLElement>('[data-feature]').forEach(el=>el.onclick=()=>{state.selectedFeature=el.dataset.feature!;render();});
  app.querySelectorAll<HTMLInputElement>('[data-attach]').forEach(el=>el.onchange=()=>{state.reviewDirty=true;state.featureNames=el.checked?[...new Set([...state.featureNames,el.dataset.attach!])]:state.featureNames.filter(f=>f!==el.dataset.attach);render();});
  app.querySelectorAll<HTMLElement>('[data-detach]').forEach(el=>el.onclick=()=>{state.featureNames=state.featureNames.filter(f=>f!==el.dataset.detach);state.reviewDirty=true;render();});
  app.querySelector<HTMLSelectElement>('#criterion-metric')?.addEventListener('change',e=>{state.metric=(e.target as HTMLSelectElement).value;state.threshold=metricSpecs[state.metric].threshold;state.op=state.metric==='PR'?'>':'>=';markPreviewStale();render();});
  app.querySelector<HTMLSelectElement>('#criterion-op')?.addEventListener('change',e=>{state.op=(e.target as HTMLSelectElement).value;markPreviewStale();render();});
  app.querySelector<HTMLInputElement>('#criterion-threshold')?.addEventListener('input',e=>{state.threshold=(e.target as HTMLInputElement).valueAsNumber;markPreviewStale();const summary=app.querySelector('.preview-summary');if(summary)summary.classList.add('stale');});
  app.querySelector<HTMLInputElement>('#criterion-threshold')?.addEventListener('change',()=>render());
  app.querySelectorAll<HTMLElement>('[data-remove-cohort]').forEach(el=>el.onclick=()=>{state.cohort=state.cohort.filter(id=>id!==Number(el.dataset.removeCohort));markPreviewStale();render();});
  app.querySelector<HTMLSelectElement>('#cohort-add')?.addEventListener('change',e=>{const id=Number((e.target as HTMLSelectElement).value);if(id&&state.cohort.length<8&&!state.cohort.includes(id)){state.cohort.push(id);markPreviewStale();render();}});
  app.querySelector('#criterion-form')?.addEventListener('submit',e=>{e.preventDefault();void previewCriterion();});
  app.querySelectorAll<HTMLInputElement>('[name="review-label"]').forEach(el=>el.onchange=()=>{let selected=Array.from(app.querySelectorAll<HTMLInputElement>('[name="review-label"]:checked')).map(i=>i.value);if(el.checked&&el.value==='NORM')selected=['NORM'];else if(el.checked)selected=selected.filter(l=>l!=='NORM');state.labels=selected;state.reviewDirty=true;render();});
  app.querySelector<HTMLTextAreaElement>('#review-note')?.addEventListener('input',e=>{state.note=(e.target as HTMLTextAreaElement).value;state.reviewDirty=true;const mark=app.querySelector('.draft-indicator');if(mark)mark.textContent='Unsaved changes';});
  app.querySelector('#save-draft')?.addEventListener('click',()=>void saveReview('draft'));
  app.querySelector('#review-form')?.addEventListener('submit',e=>{e.preventDefault();void saveReview('published');});
  app.querySelectorAll<HTMLElement>('[data-question]').forEach(el=>el.onclick=()=>setQuestion(el.dataset.question!));
  app.querySelectorAll<HTMLElement>('[data-patient-feature]').forEach(el=>el.onclick=()=>{state.patientFeature=el.dataset.patientFeature!;setQuestion(`What does the ${pretty(state.patientFeature)} measurement in this report mean?`);});
  app.querySelector<HTMLInputElement>('#patient-question')?.addEventListener('input',e=>state.question=(e.target as HTMLInputElement).value);
  app.querySelector('#question-form')?.addEventListener('submit',e=>{e.preventDefault();void askQuestion();});
  app.querySelector('#toggle-feedback')?.addEventListener('click',()=>{state.showFeedback=!state.showFeedback;render();});
  app.querySelector<HTMLTextAreaElement>('#patient-feedback')?.addEventListener('input',e=>state.feedback=(e.target as HTMLTextAreaElement).value);
  app.querySelector('#feedback-form')?.addEventListener('submit',e=>{e.preventDefault();void sendFeedback();});
  // Keep request inputs stable until the response is reconciled with this view.
  if(state.busy)app.querySelectorAll<HTMLInputElement>('input,textarea,select,button[data-remove-cohort],button[data-detach]').forEach(el=>el.disabled=true);
}
async function task(name:string,run:()=>Promise<void>){if(state.busy)return;state.busy=name;state.error='';state.message='';render();try{await run();}catch(e){state.error=e instanceof Error?e.message:String(e);}finally{state.busy='';render();}}
function applyContext(c:Obj,reset=true){
  state.ctx=c;state.sourceChanged=false;
  if(reset){state.evidence=null;state.selectedFeature='';state.preview=null;state.previewStale=false;state.messages=[];state.question='';state.feedback='';state.patientFeature='';state.showFeedback=false;state.start=0;state.cohort=defaultCohort(c.sample.ecgId,state.cases.map(s=>s.ecgId));state.collaboration={revision:0,rounds:[]};state.collaborationLoaded=false;state.expertQuestion='';state.expertFocus='';state.expertAction='auto';state.suggestionFeatures=[];}
  state.featureNames=c.review?.features?.map((f:Obj)=>f.name)||[];state.labels=c.review?.labels||[];state.note=c.review?.note||'';state.analysisRoundId=c.review?.analysisRoundId||null;state.reviewDirty=false;state.reviewBaseRevision=c.revision;urlState();
}
async function loadCase(id:number){
  if(state.busy)return false;
  if((state.reviewDirty||state.expertQuestion.trim())&&!window.confirm('This record has unsaved review changes or an unsent question. Switch records and discard them?')){render();return false;}
  let loaded=false;await task('Loading recorded ECG…',async()=>{applyContext(await fetchJson(`/api/demo/ptbxl/cases/${id}`));await loadCollaboration();loaded=true;});return loaded;
}
async function loadCollaboration(){const c=await fetchJson<Obj>(base()+'/collaboration');if(c.contextId!==state.ctx!.contextId)throw new Error('Case context changed. Refresh before continuing.');state.collaboration=c;state.collaborationLoaded=true;}
async function investigate(){
  if(state.busy||state.expertQuestion.trim().length<3)return;
  await task('Checking evidence and preparing a response. Your question is kept until this completes…',async()=>{
    if(state.sourceChanged)throw new Error('Source context changed. Refresh this record.');
    if(!state.collaborationLoaded)await loadCollaboration();
    const answer=await postJson<Obj>(base()+'/collaboration',{contextId:state.ctx!.contextId,expectedRevision:state.collaboration.revision,message:state.expertQuestion.trim(),action:state.expertAction,focus:state.expertFocus});
    state.collaboration=answer;state.expertQuestion='';state.message='Analysis returned. Check the evidence and proposed changes before accepting.';
  });
  app.querySelector('.collab-history')?.scrollTo({top:100000,behavior:'smooth'});
}
function useSuggestion(confirmReplace=true){
  const r=state.collaboration.rounds.at(-1);if(!r||r.decision!=='accepted')return;
  if(confirmReplace&&state.reviewDirty&&!window.confirm('Replace the unsaved note and attachments with this suggestion? Your saved reports will not change.'))return;
  if(r.baseReportRevision!==state.ctx!.revision){state.error='The report changed since this suggestion. Ask for a fresh analysis before using it.';render();return;}
  state.note=r.draftNote;state.featureNames=[...r.featureNames];state.suggestionFeatures=r.features;state.analysisRoundId=r.id;state.reviewDirty=true;state.section='review';state.message='Suggestion copied into an editable draft, not published. Choose labels explicitly and edit the note as needed.';render();
}
async function decideSuggestion(decision:'accepted'|'rejected'){
  if(state.busy)return;
  if(decision==='accepted'&&state.reviewDirty&&!window.confirm('Use this suggestion instead of your unsaved note and attachments? Saved reports are preserved.'))return;
  let applied=false;
  await task(decision==='accepted'?'Recording your decision…':'Keeping the suggestion as rejected…',async()=>{const r=state.collaboration.rounds.at(-1);if(!r)return;state.collaboration=await postJson(base()+'/collaboration/decision',{contextId:state.ctx!.contextId,expectedRevision:state.collaboration.revision,roundId:r.id,decision});applied=true;state.message=decision==='rejected'?'Suggestion rejected. Explain what should be checked next; the report has not changed.':'';});
  if(applied&&decision==='accepted')useSuggestion(false);
}
async function openCollaborationEvidence(name:string){state.section='evidence';await runEvidence();state.selectedFeature=name;render();}
async function inspectCase(id:number){if(await loadCase(id)){state.section='evidence';await runEvidence();}}
async function runEvidence(){await task('Running the reference feature tool…',async()=>{state.evidence=await postJson(base()+'/evidence',{contextId:state.ctx!.contextId,lead:state.lead});const features=state.evidence!.result.features;state.selectedFeature=features.find((f:Obj)=>f.judgment.status==='abnormal')?.name||features.find((f:Obj)=>f.name==='qrs_duration_ms')?.name||features[0]?.name;});}
async function previewCriterion(){await task('Checking the selected case measurements…',async()=>{if(!state.cohort.length)throw new Error('Select at least one record to preview.');const text=criterionText(state.metric,state.op,state.threshold);state.preview=await postJson(base()+'/criteria/preview',{text,contextId:state.ctx!.contextId,caseIds:[...state.cohort]});state.previewStale=false;});}
async function saveReview(status:'draft'|'published'){await task(status==='published'?'Publishing the versioned demo report…':'Saving review draft…',async()=>{const problem=validReview(state.labels,state.note);if(problem)throw new Error(problem);if(state.sourceChanged)throw new Error('Source context changed. Refresh the record before saving.');await postJson(base()+'/review',{contextId:state.ctx!.contextId,expectedRevision:state.reviewBaseRevision,labels:state.labels,note:state.note,status,featureNames:state.featureNames,analysisRoundId:state.analysisRoundId});const c=await fetchJson<Obj>(base());applyContext(c,false);state.messages=[];state.message=status==='published'?`Report v${c.publishedReport.revision} published with ${c.publishedReport.features.length} attached measurements. Open Patient to view this version.`:`Draft v${c.revision} saved. The patient still sees the last published report, if any.`;});}
async function askQuestion(){const q=state.question.trim();if(!q)return;await task('Explaining the published report…',async()=>{const history=state.messages.filter(m=>m.source!=='error'&&m.source!=='safety').slice(-6).map(m=>({role:m.role,text:m.text}));state.messages.push({role:'user',text:q});state.question='';render();try{const result=await postJson<Obj>(base()+'/question',{contextId:state.ctx!.contextId,reportRevision:state.ctx!.publishedReport.revision,question:q,history});state.messages.push({role:'assistant',text:result.answer,...result});}catch(e){state.messages.push({role:'assistant',text:e instanceof Error?e.message:String(e),source:'error'});}});app.querySelector('.dialogue-messages')?.scrollTo({top:100000,behavior:'smooth'});}
async function sendFeedback(){await task('Saving the clarification request…',async()=>{await postJson(base()+'/feedback',{contextId:state.ctx!.contextId,reportRevision:state.ctx!.publishedReport.revision,text:state.feedback});state.ctx=await fetchJson(base());state.feedback='';state.showFeedback=false;state.message='Request saved to the expert queue, linked to this report version.';});}
async function refreshContext(){await task('Refreshing the saved record…',async()=>{const c=await fetchJson<Obj>(base());if(c.contextId!==state.ctx!.contextId){if(state.reviewDirty||state.expertQuestion.trim())throw new Error('The signal or tool changed. Your unsaved note/question is kept; copy it before reloading the page.');applyContext(c);await loadCollaboration();return;}if(state.reviewDirty){state.ctx=c;state.reviewBaseRevision=c.revision;state.message='Latest published report loaded alongside your unsaved draft. Compare it before publishing.';}else applyContext(c,false);await loadCollaboration();});}
async function init(){await task('Loading case library…',async()=>{const data=await fetchJson<Obj>('/api/demo/cases');state.cases=data.samples;if(!data.samples.length)throw new Error('No recorded cases are available.');const requested=Number(params.get('case'));const id=data.samples.find((s:Obj)=>s.ecgId===requested)?.ecgId||data.samples.find((s:Obj)=>s.ecgId===(state.role==='patient'?62:26))?.ecgId||data.samples[0].ecgId;applyContext(await fetchJson(`/api/demo/ptbxl/cases/${id}`));await loadCollaboration();});}
window.addEventListener('beforeunload',e=>{if(state.reviewDirty||state.expertQuestion.trim()){e.preventDefault();e.returnValue='';}});
// Read-only refresh. Do not destroy the active text field on a remote update.
setInterval(async()=>{if(!state.ctx||state.busy||document.hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName||''))return;const id=state.ctx.sample.ecgId;try{const c=await fetchJson<Obj>(base());if(state.ctx?.sample.ecgId!==id||state.busy)return;if(c.contextId!==state.ctx.contextId){if(!state.sourceChanged){state.sourceChanged=true;state.error='The source run or evidence tool changed. Refresh this record.';render();}return;}if(c.revision!==state.ctx.revision||c.feedback.length!==state.ctx.feedback.length){const changed=c.revision!==state.ctx.revision;if(!state.reviewDirty){applyContext(c,false);}else state.ctx=c;if(changed){state.messages=[];state.message=state.reviewDirty?'A new review version is available. Your draft is kept; refresh and compare before publishing.':'A new review version is available. The report has been refreshed.';}render();}}catch{/* Preserve the current view on a transient read failure. */}},8000);
void init();
